public class Main {
    static int divide(int a, int b) {
        return a / b;
    }

    public static void main(String[] args) {
        try {
            System.out.println(divide(10, 2));
            System.out.println(divide(5, 0));
            System.out.println("not reached");
        } catch (ArithmeticException e) {
            System.out.println("cannot divide by zero");
        } finally {
            System.out.println("cleanup done");
        }
        System.out.println("program continues");
    }
}

public class Main {
    static class InsufficientBalance extends Exception {
        InsufficientBalance(String message) { super(message); }
    }

    static double withdraw(double balance, double amount) throws InsufficientBalance {
        if (amount <= 0) throw new IllegalArgumentException("amount must be positive");
        if (amount > balance) throw new InsufficientBalance("need " + (amount - balance) + " more");
        return balance - amount;
    }

    public static void main(String[] args) {
        try {
            System.out.println(withdraw(100, 40));
            System.out.println(withdraw(100, 150));
        } catch (InsufficientBalance e) {
            System.out.println("Declined: " + e.getMessage());
        } catch (IllegalArgumentException e) {
            System.out.println("Invalid: " + e.getMessage());
        }
    }
}

